(function () {
  'use strict';
  if (window.busuanziRequestSent) return;
  window.busuanziRequestSent = true;

  // 主题模板使用的容器 id（见 card_webinfo.pug / post-info.pug）
  var KEYS = ['site_uv', 'site_pv', 'page_pv'];
  // 官方接口只支持 JSONP，不存在跨域问题
  var ENDPOINT = 'https://busuanzi.ibruce.info/busuanzi';

  var callbackName = 'BusuanziCallback_' + Math.floor(1099511627776 * Math.random());
  var scriptTag = null;
  var timer = null;

  function cleanup() {
    if (timer) { clearTimeout(timer); timer = null; }
    if (scriptTag && scriptTag.parentNode) { scriptTag.parentNode.removeChild(scriptTag); }
    try { delete window[callbackName]; } catch (e) { window[callbackName] = undefined; }
  }

  // 官方接口不可达时保留原本的加载动画，不显示错误的 0
  function fail(err) {
    cleanup();
    if (window.console && console.warn) { console.warn('[busuanzi] 统计获取失败:', err); }
  }

  window[callbackName] = function (data) {
    cleanup();
    if (!data) return fail('empty response');
    for (var i = 0; i < KEYS.length; i++) {
      var key = KEYS[i];
      if (data[key] === undefined || data[key] === null) continue;
      var nodes = document.querySelectorAll('#busuanzi_' + key);
      for (var j = 0; j < nodes.length; j++) {
        nodes[j].textContent = data[key];
      }
    }
  };

  timer = setTimeout(function () { fail('timeout'); }, 10000);

  scriptTag = document.createElement('script');
  scriptTag.type = 'text/javascript';
  scriptTag.defer = true;
  scriptTag.referrerPolicy = 'no-referrer-when-downgrade';
  scriptTag.src = ENDPOINT + '?jsonpCallback=' + callbackName;
  scriptTag.onerror = function () { fail('script load error'); };
  document.head.appendChild(scriptTag);
})();
